QUEUE= r"H:/job/EMPLOYER_QUEUE.json"
R = {"host": "anacours.com", "url": URL, "v": 2, "steps": []}

# Strict confirmation: recruitment-specific, or success-banner element, or form gone
STRICT = re.compile(r"candidature a bien .t. envoy|bien .t. enregistr|votre demande a bien|"
                    r"merci de votre candidature|nous avons bien re.u|formulaire a .t. envoy", re.I)
BANNER = re.compile(r"alert-success|success-message|confirmation", re.I)

def log(step, ok, detail=""):
    R["steps"].append({"step": step, "ok": ok, "detail": str(detail)[:300]})
    print(("[OK] " if ok else "[FAIL] ") + step + " " + str(detail)[:180], flush=True)

def jit(a=2.0, b=4.5): time.sleep(random.uniform(a, b))

def commit_queue(ok, code, reason):
    try:
        q = json.load(open(QUEUE, encoding="utf-8"))
        recs = q if isinstance(q, list) else q.get("records", [])
        for r in recs:
            if "anacours" in str(r.get("website", "")).lower():
                r["status"] = "applied" if ok else "set_aside"
                r["status_code"] = code
                r["status_reason"] = reason[:200]
                r["processed_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
                r["evidence"] = str(OUT / "anacours_result.json")
                break
        json.dump(q, open(QUEUE, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        log("queue commit", True, ("applied" if ok else "set_aside") + " anacours")
    except Exception as e:
        log("queue commit", False, e)

def confirm_check(page):
    """Strict: banner element with short text, or strict phrase anywhere, AND no visible form inputs."""
    try:
        body = (page.locator("body").inner_text() or "")
    except Exception:
        return None
    strict_hit = STRICT.search(body)
    banner = page.evaluate("""() => {
      const els = document.querySelectorAll('[class*=alert-success],[class*=success],[class*=confirmation],[role=alert]');
      for (const el of els){ const r=el.getBoundingClientRect(); if(r.width>0&&r.height>0){
        const t=(el.textContent||'').trim().slice(0,300); if(t) return t; } } return null; }""")
    form_gone = page.evaluate("""() => {
      const vis = el => {const r=el.getBoundingClientRect(), s=getComputedStyle(el);
        return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'};
      return [...document.querySelectorAll('form input:not([type=hidden]),form textarea,form select')].filter(vis).length; }""")
    if (strict_hit or banner) and form_gone == 0:
        return (strict_hit.group(0) if strict_hit else "") + " | banner=" + str(banner)[:120]
    return None

prof = json.load(open(PROF, encoding="utf-8"))
