            "prenom": " ".join(ident["name"].split()[:-1]),
            "email": ident["email"],
            "telephone": ident["phone"],
            "cp": "97410",
            "ville": "Saint-Pierre",
            "diplome": "Cambridge CELTA (2026)",
        }

        def state():
            return page.evaluate("""() => {
              const vis = el => {const r=el.getBoundingClientRect(), s=getComputedStyle(el);
                return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'};
              const ids=['civilite','nom','prenom','email','telephone','cp','ville','diplome'];
              return {
                ids: ids.map(id=>{const el=document.getElementById(id);
                    return el&&vis(el)?{id, val:el.value}:null}).filter(Boolean),
                matieres: [...document.querySelectorAll('input[name="matieres[]"]')].filter(vis).length,
                cv: !!document.getElementById('cv'),
                ta: [...document.querySelectorAll('textarea')].filter(vis).map(t=>t.id)};}""")

        for step in range(12):
            st = state()
            print(f"--- step {step}: fields={[f['id'] for f in st['ids']]} matieres={st['matieres']} ta={st['ta']}", flush=True)
            acted = False

            if st["matieres"] > 0:
                try:
                    lab = page.locator('label:has(input[name="matieres[]"]):has-text("Anglais")').first
                    if lab.is_visible(timeout=1500) and page.locator('input[name="matieres[]"]:checked').count() == 0:
                        lab.click(); jit(); log("matieres=Anglais", True); acted = True
                except Exception as e:
                    log("matieres", False, e)

            for f in st["ids"]:
                fid = f["id"]
                if fid == "civilite" or (f.get("val") or "").strip():
                    continue
                val = FIELD_VALUES.get(fid)
                if not val:
                    continue
                try:
                    page.fill("#" + fid, val); jit(); log("fill " + fid, True, val); acted = True
                    if fid == "cp":
                        page.wait_for_timeout(1800)
                        try:
                            sugg = page.locator("li:has-text('Saint-Pierre')").first
                            if sugg.is_visible(timeout=2500):
                                sugg.click(); jit(); log("ville suggestion", True)
                        except Exception:
                            pass
                except Exception as e:
                    log("fill " + fid, False, e)

            try:
                page.evaluate("""() => {const c=document.getElementById('civilite');
                    if(c && !c.value){c.value='M.'; c.dispatchEvent(new Event('change',{bubbles:true}));}}""")
            except Exception:
                pass

            if st["cv"] and not R.get("cv"):
                try:
                    page.set_input_files("#cv", CV); jit(); R["cv"] = True
                    log("CV attached", True); acted = True
                except Exception as e:
                    log("CV attach", False, e)

            if "vision_enseignement" in st["ta"]:
                try:
                    ta = page.locator("#vision_enseignement")
                    if not (ta.first.input_value() or "").strip():
                        ta.first.fill(vals["Cover note"]); jit(); log("vision textarea", True); acted = True
                except Exception as e:
                    log("textarea", False, e)

            page.screenshot(path=str(OUT / f"anacours_v2_{step:02d}.png"), full_page=True)

            # advance (final submit words included; confirmation checked ONLY after click)
            btn, final = None, False
            for pat, is_final in [("Envoyer", True), ("Envoyer ma candidature", True), ("Terminer", True),
                                  ("Postuler", True), ("Je postule", True), ("Valider", False),
                                  ("Continuer", False), ("Suivant", False)]:
                try:
                    loc = page.locator(f'button:has-text("{pat}")')
                    for i in range(loc.count()):
                        if loc.nth(i).is_visible():
                            btn, final = loc.nth(i), is_final; break
                    if btn: break
                except Exception:
                    pass
            if not btn:
                try:
                    loc = page.locator('input[type=submit]')
                    for i in range(loc.count()):
                        if loc.nth(i).is_visible():
                            btn, final = loc.nth(i), True; break
                except Exception:
                    pass

            if btn:
                txt = (btn.text_content() or "").strip()[:40]
                log(("FINAL CLICK '" if final else "advance '") + txt + "'", True)
                btn.click(); jit(2.5, 4.5)
                page.wait_for_timeout(2000)
                conf = confirm_check(page)
                page.screenshot(path=str(OUT / f"anacours_v2_{step:02d}_after.png"), full_page=True)
                if conf:
                    submitted = True
                    body = (page.locator("body").inner_text() or "")[:3000]
                    (OUT / "anacours_final_body.txt").write_text(body, encoding="utf-8")
                    log("SUBMIT VERIFIED", True, conf[:200]); break
                if final:
