                        submitted = True; log("SUBMIT VERIFIED (delayed)", True, conf[:200]); break
            elif not acted:
                conf = confirm_check(page)
                if conf:
                    submitted = True; log("SUBMIT VERIFIED (no btn)", True, conf[:200])
                else:
                    log("stalled", False, "no button, no fields, no confirmation"); break
                break

        if not submitted:
            body = (page.locator("body").inner_text() or "")[:3000]
            (OUT / "anacours_end_body.txt").write_text(body, encoding="utf-8")
